"""Launching an isolated Ghostty instance and driving it via AppleScript."""

from __future__ import annotations

import os
import plistlib
import shlex
import signal
import subprocess
import time
from dataclasses import dataclass, field
from pathlib import Path

from . import appleevents as ae
from .appleevents import AppleEventClient, AppleEventError
from .util import CheckFailed, HarnessError, log, wait_until

# Kept deliberately minimal and deterministic. `config-default-files = false`
# on the command line means the user's own config files are never read.
CONFIG = """\
# Generated by test/tmux-e2e. Do not edit.
command = {shell}
shell-integration = none
window-save-state = never
confirm-close-surface = false
quit-after-last-window-closed = false
macos-applescript = true
auto-update = off
app-notifications = no-clipboard-copy
clipboard-write = allow
window-width = 110
window-height = 32
font-size = 12
"""

# The shell used by Ghostty's own (non-tmux) terminals: plain /bin/sh with a
# recognisable prompt and nothing from the user's rc files.
SHELL_WRAPPER = """\
#!/bin/sh
export PS1='gateway$ '
exec /bin/sh
"""


# -- GUI state model ---------------------------------------------------------


@dataclass(frozen=True)
class Terminal:
    id: str
    name: str
    tty: str
    pid: int
    cwd: str


@dataclass(frozen=True)
class Tab:
    id: str
    window_id: str
    name: str
    index: int
    selected: bool
    focused_terminal: str | None
    terminals: tuple[Terminal, ...]


@dataclass(frozen=True)
class Window:
    id: str
    name: str
    selected_tab: str | None
    tabs: tuple[Tab, ...]


@dataclass(frozen=True)
class Snapshot:
    windows: tuple[Window, ...] = field(default_factory=tuple)

    @property
    def tabs(self) -> list[Tab]:
        return [t for w in self.windows for t in w.tabs]

    @property
    def terminals(self) -> list[Terminal]:
        return [x for t in self.tabs for x in t.terminals]

    def tab_of(self, terminal_id: str) -> Tab | None:
        for t in self.tabs:
            if any(x.id == terminal_id for x in t.terminals):
                return t
        return None

    def describe(self) -> str:
        parts = []
        for w in self.windows:
            tabs = []
            for t in w.tabs:
                sel = "*" if t.id == w.selected_tab else ""
                terms = ",".join(x.id[:8] + ("^" if x.id == t.focused_terminal else "") for x in t.terminals)
                tabs.append(f"{t.name!r}{sel}[{terms}]")
            parts.append(f"win {w.name!r}: " + " ".join(tabs))
        return " | ".join(parts) or "<no windows>"


# -- AppleScript -------------------------------------------------------------

# AppleEventError is what a failed scripting command raises; scenarios treat
# it as a test failure (the harness keeps going).
AppleScriptError = AppleEventError

# Four-character codes from macos/Ghostty.sdef.
WINDOW, TAB, TERMINAL = "Gwnd", "Gtab", "Gtrm"
SPLIT_DIRECTIONS = {"right": "GSrt", "left": "GSlf", "down": "GSdn", "up": "GSup"}
MOUSE_BUTTONS = {"left": "GMlf", "right": "GMrt", "middle": "GMmd"}


class GhosttyApp:
    """An isolated Ghostty.app instance launched from its executable."""

    def __init__(self, bundle: Path, workdir: Path, log_path: Path) -> None:
        self.bundle = bundle.resolve()
        self.executable = self.bundle / "Contents" / "MacOS" / "ghostty"
        if not self.executable.is_file():
            raise HarnessError(f"not a Ghostty app bundle (missing {self.executable})")
        with (self.bundle / "Contents" / "Info.plist").open("rb") as f:
            self.bundle_id: str = plistlib.load(f).get("CFBundleIdentifier", "?")

        self.workdir = workdir
        self.tmpdir = workdir / "tmp"
        self.tmpdir.mkdir(parents=True, exist_ok=True)
        self.log_path = log_path
        self.shell = workdir / "shell.sh"
        self.shell.write_text(SHELL_WRAPPER)
        self.shell.chmod(0o755)
        self.config = workdir / "config.ghostty"
        self.write_config()
        self.proc: subprocess.Popen | None = None
        self._log_file = None
        self._ae: AppleEventClient | None = None

    def write_config(self, extra: str = "") -> None:
        """(Re)write the generated config; `extra` lines override the defaults.

        Takes effect at the next launch.
        """
        self.config.write_text(CONFIG.format(shell=shlex.quote(str(self.shell))) + extra)

    # -- lifecycle ----------------------------------------------------------

    def launch(self, timeout: float = 30.0) -> None:
        env = {k: v for k, v in os.environ.items() if k not in ("TMUX", "TMUX_PANE")}
        env.update(
            {
                # Temp files (e.g. write_screen_file output) land here so the
                # harness can find them and nothing leaks into the real $TMPDIR.
                "TMPDIR": str(self.tmpdir) + "/",
                # Belt and braces next to --config-default-files=false.
                "XDG_CONFIG_HOME": str(self.workdir / "xdg"),
                "GHOSTTY_LOG": "stderr",
            }
        )
        argv = [
            str(self.executable),
            "--config-default-files=false",
            f"--config-file={self.config}",
        ]
        log(f"launching {shlex.join(argv)}")
        self._log_file = self.log_path.open("ab")
        self.proc = subprocess.Popen(
            argv,
            env=env,
            cwd=self.workdir,
            stdin=subprocess.DEVNULL,
            stdout=self._log_file,
            stderr=subprocess.STDOUT,
            start_new_session=True,
        )

        def ready() -> bool:
            if not self.alive():
                raise HarnessError(f"Ghostty exited during launch (code {self.proc.returncode}); see {self.log_path}")
            # A surface that failed to initialize still shows up as an
            # (inert) terminal over AppleScript, so check the log too.
            for line in self.log_path.read_text(errors="replace").splitlines():
                if "error initializing surface" in line:
                    raise HarnessError(
                        f"Ghostty could not create a terminal surface: {line.strip()}\n  full log: {self.log_path}"
                    )
            try:
                return len(self.snapshot().terminals) >= 1
            except AppleScriptError:
                return False

        try:
            wait_until(ready, timeout=timeout, interval=0.5, desc="Ghostty to open a terminal and answer AppleScript")
        except CheckFailed as exc:
            errors = [line for line in self.log_path.read_text(errors="replace").splitlines() if "error" in line]
            hint = ("\n  app log errors:\n    " + "\n    ".join(errors[-5:])) if errors else ""
            raise HarnessError(f"{exc}{hint}\n  full log: {self.log_path}") from exc

    def quit(self, timeout: float = 10.0) -> None:
        """Quit the way a user does (the `quit` Apple Event), so that the app
        gets to save its window state, and wait for it to exit."""
        if not self.alive():
            return
        try:
            self.ae.send("aevtquit")
        except AppleScriptError as exc:
            log(f"quit: {exc}")
        try:
            self.proc.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            log("quit timed out; terminating")
        self.terminate()

    def relaunch(self, extra_config: str = "", timeout: float = 30.0) -> None:
        """Quit and start again, with `extra_config` added to the config."""
        self.quit()
        self.write_config(extra_config)
        self.launch(timeout=timeout)

    @property
    def pid(self) -> int:
        if self.proc is None:
            raise HarnessError("Ghostty is not running")
        return self.proc.pid

    def alive(self) -> bool:
        return self.proc is not None and self.proc.poll() is None

    def terminate(self, timeout: float = 5.0) -> None:
        if self.proc is None:
            return
        if self.alive():
            self.proc.send_signal(signal.SIGTERM)
            try:
                self.proc.wait(timeout=timeout)
            except subprocess.TimeoutExpired:
                self.proc.kill()
                self.proc.wait(timeout=timeout)
        if self._log_file is not None:
            self._log_file.close()
            self._log_file = None

    # -- AppleScript calls --------------------------------------------------

    @property
    def ae(self) -> AppleEventClient:
        if self._ae is None or self._ae.pid != self.pid:
            self._ae = AppleEventClient(self.pid)
        return self._ae

    def version(self) -> str:
        return self.ae.get(ae.prop("vers"))

    def activate(self) -> None:
        """Make the test instance the active app (the standard `activate`
        event, addressed by pid like everything else).

        Focus follows the key window, and tmux follows focus, so scenarios
        about either need the app to be active. Another app in front --
        a full screen one in particular -- otherwise keeps it inactive.
        """
        self.ae.send("miscactv")

    def ensure_active(self, timeout: float = 5.0) -> bool:
        """Activate the app and wait until it is the active one.

        Returns False if it never became active: macOS lets the app in
        front keep focus when someone is using it, and then nothing that
        depends on a key window (focus, and so tmux's active pane and
        window) can be checked.
        """
        from . import ax

        def active() -> bool:
            try:
                if ax.is_frontmost(self.pid):
                    return True
            except ax.AxUnavailable:
                return True  # can't tell; carry on and let scenarios decide
            self.activate()
            return False

        try:
            wait_until(active, timeout=timeout, interval=0.3, desc="Ghostty to become the active app")
            return True
        except CheckFailed:
            return False

    def snapshot(self) -> Snapshot:
        """Read the whole window -> tab -> terminal tree."""
        get, prop = self.ae.get, ae.prop

        def optional(spec):
            try:
                return get(spec)
            except AppleEventError:
                return None

        windows = []
        for wid in get(prop("ID", ae.every(WINDOW))) or []:
            w = ae.by_id(WINDOW, wid)
            tabs = []
            for tid in get(prop("ID", ae.every(TAB, w))) or []:
                t = ae.by_id(TAB, tid, w)
                terminals = []
                for xid in get(prop("ID", ae.every(TERMINAL, t))) or []:
                    x = ae.by_id(TERMINAL, xid, t)
                    terminals.append(
                        Terminal(
                            id=xid,
                            name=get(prop("pnam", x)) or "",
                            # tty/pid are newer than the rest of the
                            # dictionary; tolerate builds without them.
                            tty=optional(prop("Gtty", x)) or "",
                            pid=optional(prop("Gpid", x)) or 0,
                            cwd=optional(prop("Gwdr", x)) or "",
                        )
                    )
                tabs.append(
                    Tab(
                        id=tid,
                        window_id=wid,
                        name=get(prop("pnam", t)) or "",
                        index=get(prop("pidx", t)) or 0,
                        selected=bool(get(prop("GTsl", t))),
                        focused_terminal=optional(prop("ID", prop("GTfT", t))),
                        terminals=tuple(terminals),
                    )
                )
            windows.append(
                Window(
                    id=wid,
                    name=get(prop("pnam", w)) or "",
                    selected_tab=optional(prop("ID", prop("GWsT", w))),
                    tabs=tuple(tabs),
                )
            )
        return Snapshot(tuple(windows))

    def _terminal(self, terminal_id: str):
        return ae.by_id(TERMINAL, terminal_id)

    def _tab(self, tab: Tab):
        return ae.by_id(TAB, tab.id, ae.by_id(WINDOW, tab.window_id))

    def input_text(self, terminal: str, text: str) -> None:
        self.ae.send("GhstInTx", ae.text(text), GItT=self._terminal(terminal))

    def send_key(self, terminal: str, key: str, modifiers: str | None = None) -> None:
        self.ae.send(
            "GhstSKey",
            ae.text(key),
            GKeT=self._terminal(terminal),
            GKeM=ae.text(modifiers) if modifiers else None,
        )

    def type_line(self, terminal: str, line: str) -> None:
        """Type a command line as a user would and press Enter."""
        self.input_text(terminal, line)
        self.send_key(terminal, "enter")

    def perform(self, terminal: str, action: str) -> bool:
        """Run a Ghostty keybinding action (e.g. "new_split:right")."""
        return bool(self.ae.send("GhstPfAc", ae.text(action), GonT=self._terminal(terminal)))

    def split(self, terminal: str, direction: str = "right") -> str:
        new = self.ae.send("GhstSplt", self._terminal(terminal), GSpd=ae.enum(SPLIT_DIRECTIONS[direction]))
        return self.ae.get(ae.prop("ID", new))

    def focus(self, terminal: str) -> None:
        self.ae.send("GhstFcus", self._terminal(terminal))

    def close(self, terminal: str) -> None:
        self.ae.send("GhstClos", self._terminal(terminal))

    def select_tab(self, tab: Tab) -> None:
        self.ae.send("GhstSlTb", self._tab(tab))

    def close_tab(self, tab: Tab) -> None:
        self.ae.send("GhstClTb", self._tab(tab))

    def close_window(self, window_id: str) -> None:
        self.ae.send("GhstClWn", ae.by_id(WINDOW, window_id))

    def new_window(self, command: str | None = None) -> str:
        """Open a window (optionally running `command`) and return its id."""
        config = ae.record(GScC=ae.text(command)) if command else None
        new = self.ae.send("GhstNWin", GNwS=config)
        return self.ae.get(ae.prop("ID", new))

    def activate_window(self, window_id: str) -> None:
        self.ae.send("GhstAcWn", ae.by_id(WINDOW, window_id))

    def mouse_move(self, terminal: str, x: float, y: float) -> None:
        """Move the mouse to (x, y), in points from the terminal's top left."""
        self.ae.send("GhstSMPs", GMpX=_real(x), GMpY=_real(y), GMpT=self._terminal(terminal))

    def mouse_button(self, terminal: str, button: str = "left", press: bool = True) -> None:
        self.ae.send(
            "GhstSMBt",
            ae.enum(MOUSE_BUTTONS[button]),
            GMbA=ae.enum("GIpr" if press else "GIrl"),
            GMbT=self._terminal(terminal),
        )

    def click(self, terminal: str, x: float, y: float, button: str = "left") -> None:
        self.mouse_move(terminal, x, y)
        self.mouse_button(terminal, button, press=True)
        self.mouse_button(terminal, button, press=False)

    def scroll(self, terminal: str, dy: float) -> None:
        """Send a (non-precision) mouse wheel event; positive scrolls up."""
        self.ae.send("GhstSMSc", GMsX=_real(0.0), GMsY=_real(dy), GMsT=self._terminal(terminal))

    def close_all_windows(self, timeout: float = 10.0) -> None:
        for w in self.snapshot().windows:
            try:
                self.close_window(w.id)
            except AppleScriptError as exc:
                log(f"close window {w.id}: {exc}")
        wait_until(lambda: not self.snapshot().windows, timeout=timeout, desc="all Ghostty windows to close")

    # -- screen contents ----------------------------------------------------

    def read_screen(self, terminal: str, timeout: float = 5.0) -> str:
        """Return the screen text of a terminal, scrollback included.

        AppleScript has no "contents" property, so this runs the
        `write_screen_file:copy` action, which dumps the screen to a file
        under our private $TMPDIR (and puts its path on the clipboard; the
        caller's clipboard text is saved and restored around it).
        """
        return self._read_dump(terminal, "write_screen_file:copy", "screen.txt", timeout)

    def read_scrollback(self, terminal: str, timeout: float = 5.0) -> str:
        """Return the scrollback (history above the screen) of a terminal.

        Runs `write_scrollback_file:copy`. A terminal with no history
        writes no file, so that times out.
        """
        return self._read_dump(terminal, "write_scrollback_file:copy", "history.txt", timeout)

    def _read_dump(self, terminal: str, action: str, name: str, timeout: float) -> str:
        before = {p: p.stat().st_mtime_ns for p in self.tmpdir.rglob(name)}
        saved_clipboard = pbpaste()
        try:
            if not self.perform(terminal, action):
                raise AppleScriptError(f"{action} was not performed")

            def new_file() -> Path | None:
                for p in self.tmpdir.rglob(name):
                    if before.get(p) != p.stat().st_mtime_ns:
                        return p
                return None

            path = wait_until(new_file, timeout=timeout, interval=0.1, desc="screen dump file")
        finally:
            pbcopy(saved_clipboard)
        text = path.read_text(errors="replace")
        path.unlink(missing_ok=True)
        return text


def _real(value: float):
    return ae.D.descriptorWithDouble_(value)


def pbpaste() -> str | None:
    proc = subprocess.run(["pbpaste"], capture_output=True)
    return proc.stdout.decode(errors="surrogateescape") if proc.returncode == 0 else None


def pbcopy(text: str | None) -> None:
    if text is None:
        return
    # Give the app a moment to finish its own clipboard write first.
    time.sleep(0.05)
    subprocess.run(["pbcopy"], input=text.encode(errors="surrogateescape"))
